import re
# find function starts: lines whose instruction is 'push %rbp' following a ret/nop padding, or 'endbr64'
def find_starts(f):
    lines = open(f).read().splitlines()
    starts = []
    for i, l in enumerate(lines):
        m = re.match(r'\s*([0-9a-f]+):\s+([0-9a-f ]+)\t(.*)', l)
        if m and m.group(3).strip() in ('push %rbp','endbr64'):
            starts.append(int(m.group(1),16))
    return sorted(set(starts))
sv = find_starts('ptp_vul.asm')
sf = find_starts('ptp_fix.asm')
print('vul starts:', [hex(x) for x in sv if x < 0x42c000])
print('fix starts:', [hex(x) for x in sf if x < 0x42c000])
PYEOF"}

