import re
def parse(f):
    ins = []
    for l in open(f):
        m = re.match(r'\s*([0-9a-f]+):\s+([0-9a-f ]+?)\s{2,}(.*)', l)
        if m:
            ins.append((int(m.group(1),16), m.group(3).strip()))
    return ins
vi = parse('ptp_vul.asm')
fi = parse('ptp_fix.asm')
# Find function start: scan backwards from first ref (0x42bfb9 vul / 0x42c03a fix) for 'push %rbp' or typical prologue with sub $large,%rsp
def find_start(ins, refaddr):
    for i,(a,t) in enumerate(ins):
        if a >= refaddr:
            # scan back
            for j in range(i, max(0,i-200), -1):
                if 'push   %rbp' in ins[j][1] or 'endbr64' in ins[j][1]:
                    return ins[j][0]
            return None
print('vul start', hex(find_start(vi, 0x42bfb9) or 0))
print('fix start', hex(find_start(fi, 0x42c03a) or 0))
